"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["80423"],{24781(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.no_exigencia.quantidade_minima_fora_dos_limites","status":422,"titulo":"quantidadeMinima de um grupo OU/N-de deve estar entre 1 e o n\xfamero de filhos"},"descricao":{"codigo":"uniplus.selecao.no_exigencia.quantidade_minima_fora_dos_limites","requisitos":["UNI-REQ-0067"],"oQueAconteceu":["Um n\xf3 grupo com `tipo` igual a `OU` declara `quantidadeMinima` menor que\\n1, ou maior que o n\xfamero de filhos do pr\xf3prio grupo. Em `OU`/N-de,\\n`quantidadeMinima` conta quantos filhos precisam estar satisfeitos para\\no grupo inteiro ser satisfeito \u2014 pedir menos de 1 n\xe3o exige nada, e\\npedir mais do que existem filhos \xe9 uma exig\xeancia que nenhuma combina\xe7\xe3o\\nde respostas jamais cumpre.","Diferente de um grupo `E` (que nunca tem cardinalidade pr\xf3pria \u2014 ver\\n[`quantidade_minima_proibida_em_grupo_e`](/erros/uniplus.selecao.no_exigencia.quantidade_minima_proibida_em_grupo_e)),\\nesta \xe9 a confer\xeancia de cardinalidade do ramo `OU`. Roda como a primeira\\nconfer\xeancia espec\xedfica desse ramo. Sequencial: nunca acumula com nenhuma\\noutra causa desta s\xe9rie."],"comoResolver":["Ajuste `quantidadeMinima` para um valor entre 1 e o n\xfamero de filhos do\\ngrupo, inclusive. Um valor menor que 1 no `PUT` responde com\\n`uniplus.validacao`, n\xe3o com este c\xf3digo \u2014 mas a corre\xe7\xe3o \xe9 a mesma."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"No exigencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);